const down = new Set(), pressed = new Set(), released = new Set();
addEventListener('keydown', e => { if (!down.has(e.code)) pressedRaw.add(e.code); down.add(e.code); });
addEventListener('keyup',   e => { down.delete(e.code); releasedRaw.add(e.code); });

// 프레임 시작에 이번 프레임 pressed/released 를 확정(폴링) — 에지 감지
// pressed = 지난 프레임엔 안 눌렸는데 지금 눌림(막 눌린 순간)
if (pressed.has('Space')) jump();   // 한 번(점프)
if (down.has('ArrowRight')) moveRight();   // 지속(이동)
if (released.has('Space')) endChargeJump();   // 놓을 때(가변 점프)

const rules = {
  idle:   { move: 'run',  jump: 'air',  attack: 'attack' },
  run:    { move: 'run',  jump: 'air',  attack: 'attack' },
  air:    { move: 'air',  attack: 'airAttack' },   // jump 없음 = 2단 점프 미정의
  attack: { /* 애니메이션 끝나면 idle */ },
};
function handleInput(state, input) {
  return rules[state]?.[input] ?? state;   // 정의 안 된 전이는 상태 유지
}
// if 문이 5개를 넘으면 상태 기계로 — 상태 × 입력을 표로 적으면 버그가 보인다
// 한 번에 한 상태(겹침 없음) · 전이 명시적 · 빈칸 = 미정의 동작

// 누른 순간: 점프 입력을 잠깐 기억
if (pressed.has('Space')) jumpBuffer = 0.12;   // 0.12초 버퍼
jumpBuffer -= dt;   // 매 프레임 줄임

// 착지했을 때 버퍼가 살아 있으면 바로 점프 (그 사이 뗐어도)
if (grounded && jumpBuffer > 0) {
  jump();
  jumpBuffer = 0;
}
// 착지 직전에 눌러도 착지하며 점프 → 「눌렀는데 안 됨」 해소
// 공격·대시 등 타이밍 입력에 모두 적용 (버퍼 0.1~0.15초)

coyote = grounded ? 0.1 : coyote - dt;   // 땅이면 리셋, 떨어지면 줄어듦

// 점프 허용: 코요테가 살아 있으면(막 떨어졌어도 0.1초는 OK)
if ((pressed.has('Space') || jumpBuffer > 0) && coyote > 0) {
  jump(); coyote = 0; jumpBuffer = 0;
}
// 버퍼(조금 이른 입력) + 코요테(조금 늦은 발판 이탈) = 양쪽으로 관용
// 선입력 취소: 이미 시작한 동작을 다른 입력으로 캔슬·연결(콤보)
// 이 셋(버퍼·코요테·선입력)만 넣어도 조작감이 확 좋아진다

// 매핑: 장치 입력 → 추상 액션 (한 곳에)
const bindings = {
  jump:   ['Space', 'GamepadA', 'TouchJump'],
  move:   ['ArrowLeft', 'ArrowRight', 'GamepadStick', 'TouchDpad'],
  attack: ['KeyX', 'GamepadX', 'TouchAttack'],
};
// 게임 로직은 액션만 본다 (장치 무관)
